import{z as i,x as A,o as d,c as B,q as o,j as r,D as E,d as l,s as p,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"显影：搅拌与 puddle","description":"","frontmatter":{"title":"显影：搅拌与 puddle","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/develop-puddle.md","filePath":"litho/develop-puddle.md","lastUpdated":1791413859000}'),n={name:"litho/develop-puddle.md"};function u(D,a,h,m,c,f){const t=A("Mermaid");return d(),B("div",null,[a[2]||(a[2]=o('<h1 id="显影-搅拌与-puddle" tabindex="-1">显影：搅拌与 puddle <a class="header-anchor" href="#显影-搅拌与-puddle" aria-label="Permalink to &quot;显影：搅拌与 puddle&quot;">​</a></h1><div class="epigraph"><p>溶解速率曲线给出材料能走多快；轨道给出液膜是静止 puddle 还是流动更新。传质一变，CD 跟着变。</p><footer>—— 对照 Mack 溶解模型与轨道 puddle develop 公开流程</footer></div><p><a href="/litho/soft-bake">上一课</a>给出固体膜。主干已有 <a href="/litho/resist-contrast-curve">衬度曲线</a> 与 <a href="/litho/dissolution-mack">Mack 溶解</a>。缺口是实现：显影液怎么铺、停多久、要不要搅。本课钉 puddle 与搅拌，化学物种留给下一课 TMAH。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实验室喷淋与厂内 puddle 的边界层不同。静止 puddle 里溶解产物积累，局部 pH 与抑制剂浓度漂；旋转喷淋更新液体，但可能引入溅射缺陷。把所有 CD 偏差写成剂量，会漏掉这一段传质。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型正胶：喷嘴铺满 TMAH puddle，静止数秒至数十秒，再漂洗。时间是剂量之外的第二旋钮：过显影吃线宽，欠显影留残胶。搅拌（scan nozzle、轻微旋转）减薄边界层，加快到达体相速率。配方写清：铺液转速、puddle 时间、是否间歇旋转。</p><p><span class="marginnote">为什么重要：显影不足留下的残膜在 SEM 上和离焦、欠剂量很像；过显影吃掉的线宽又会被误记成「刻蚀腰斩」。把轨道参数（puddle 时间、搅拌）写进配方并固定，才谈得上把 CD 漂移归因给光刻剂量——否则两类旋钮互相背锅。</span></p>',8)),(d(),r(s,null,{default:E(()=>[p(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SOLID%5B%22%E7%83%A4%E5%90%8E%E8%83%B6%22%5D%20--%3E%20PUD%5B%22%E9%93%BA%E6%B6%B2%20puddle%22%5D%0A%20%20PUD%20--%3E%20DISS%5B%22%E6%BA%B6%E8%A7%A3%20%2F%20%E4%BC%A0%E8%B4%A8%22%5D%0A%20%20DISS%20--%3E%20RINSE%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%86%B2%E6%B4%97%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"EUV 薄胶的绝对溶解量小，但对残膜与残渣更敏感。同一 puddle 时间，DUV 厚胶与 EUV 薄胶不是同一个工艺窗口。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"溶解是表面反应加产物扩散。边界层厚，有效速率被扩散限制，衬度曲线的「实验室搅拌」假设失效。产物若抑制溶解，静止 puddle 会自减速——看起来像欠剂量。",-1)),(d(),r(s,null,{default:E(()=>[p(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUD%5B%22%E9%9D%99%E6%AD%A2%20puddle%22%5D%20--%3E%20BL%5B%22%E6%BA%B6%E8%A7%A3%E4%BA%A7%E7%89%A9%E5%9C%A8%E7%95%8C%E9%9D%A2%E5%A0%86%E7%A7%AF%22%5D%0A%20%20BL%20--%3E%20GR%5B%22%E5%B1%80%E9%83%A8%20pH%20%E4%B8%8E%E6%8A%91%E5%88%B6%E5%89%82%E6%B5%93%E5%BA%A6%E6%BC%82%E7%A7%BB%22%5D%0A%20%20GR%20--%3E%20SL%5B%22%E8%A1%A8%E9%9D%A2%E5%8F%8D%E5%BA%94%E5%8F%98%E6%85%A2%3A%20%E8%87%AA%E5%87%8F%E9%80%9F%22%5D%0A%20%20SL%20--%3E%20LOOK%5B%22%E7%97%87%E7%8A%B6%E7%9C%8B%E8%B5%B7%E6%9D%A5%E5%83%8F%E6%AC%A0%E5%89%82%E9%87%8F%22%5D%0A%20%20STIR%5B%22%E6%90%85%E6%8B%8C%20%2F%20%E9%97%B4%E6%AD%87%E6%97%8B%E8%BD%AC%22%5D%20--%3E%20THIN%5B%22%E8%BE%B9%E7%95%8C%E5%B1%82%E5%8F%98%E8%96%84%22%5D%0A%20%20THIN%20--%3E%20REF%5B%22%E7%95%8C%E9%9D%A2%E6%B6%B2%E4%BD%93%E4%B8%8D%E6%96%AD%E6%9B%B4%E6%96%B0%22%5D%0A%20%20REF%20--%3E%20FAST%5B%22%E9%80%9F%E7%8E%87%E5%9B%9E%E5%88%B0%E4%BD%93%E7%9B%B8%E6%BA%B6%E8%A7%A3%E6%9E%81%E9%99%90%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">直觉类比：边界层像咖啡杯底没搅到的那层糖浆——糖化得再快，不搅也堆在杯底，越堆越化不动。喷嘴扫一圈等于用勺子搅一下：界面换上新液体，溶解立刻回全速。CD 偏差就是这杯「搅没搅匀」的读数。</span></p><p><span class="marginnote">术语翻译：puddle（显影液潭）就是把显影液铺满整片晶圆、让它像一滩静止的水潭停几秒到几十秒的手段——不是喷淋冲洗，而是「泡」。传质快慢全看这潭液体的界面更新程度：死水潭自减速，活水潭贴着体相速率走。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写负胶交联显影的溶剂体系细节。下一课钉 TMAH 浓度与表面活性剂，不改 puddle 运动学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>puddle 的传质与溶解曲线同样决定 CD。</li><li>搅拌与时间是轨道参数，不是扫描仪剂量的别名。</li><li>出处：Mack 溶解；轨道 puddle 通识。</li></ul>',6))])}const C=i(n,[["render",u]]);export{T as __pageData,C as default};
